 (JavaInterface.getInstance () . USB_SetThermometryBasicParam (userId, basicTempParam) ) { checkCommandState (userId) { XLog.v ("$TAG initConfig () set to $it") } } else { XLog.e ("$TAG initConfig () set to ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } } else { XLog.e ("$TAG initConfig () ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } / *  *  *  * / fun shutter (userId: Int) { JavaInterface.getInstance () . USB_SetImageManualCorrect (userId) } / *  *  *  * / suspend fun setAutoShutter (userId: Int, isAutoShutter: Boolean) { XLog.i ("$TAG setAutoShutter () ${if (isAutoShutter) "" else ""} ") val param = USB_SYSTEM_SERIAL_DATA_TRANSMISSION () param.byMode = 2 // 0 - 1 - 2 - param.wDeviceCMDFlag = 0 param.dwDeviceCMD = 0x2001 // code param.dwValue = if (isAutoShutter) 1 else 0 if (JavaInterface.getInstance () . USB_SetSystemSerialData (userId, param) ) { checkCommandState (userId) { XLog.v ("$TAG setAutoShutter () $it") } } else { XLog.e ("$TAG setAutoShutter () ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } / *  *  * start * / suspend fun startCorrect (userId: Int) { XLog.i ("$TAG startCorrect () start ") val param = USB_SYSTEM_SERIAL_DATA_TRANSMISSION () param.byMode = 2 // 0 - 1 - 2 - param.wDeviceCMDFlag = 0 param.dwDeviceCMD = 0xf026 // code param.dwValue = 2 if (JavaInterface.getInstance () . USB_SetSystemSerialData (userId, param) ) { checkCommandState (userId) { XLog.v ("$TAG startCorrect () $it") } } else { XLog.e ("$TAG startCorrect () ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } / *  *  * set to. * @param contrast range `[0, 100]` * / suspend fun setContrast (userId: Int, contrast: Int) { XLog.i ("$TAG setContrast ($contrast) set to ") val param = USB_IMAGE_CONTRAST () param.dwContrast = contrast if (JavaInterface.getInstance () . USB_SetImageContrast (userId, param) ) { checkCommandState (userId) { XLog.v ("$TAG setContrast () set to $it") } } else { XLog.e ("$TAG setContrast () set to ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } / *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  * ImageEnhancement *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  * / / *  *  * set to () * / suspend fun setEnhanceLevel (userId: Int, level: Int) { val param = USB_IMAGE_ENHANCEMENT () if (JavaInterface.getInstance () . USB_GetImageEnhancement (userId, param) ) { if (param.dwLSEDetailLevel == level) { return } XLog.i ("$TAG setEnhanceLevel () ${param.dwLSEDetailLevel}->$level") param.dwLSEDetailLevel = level if (JavaInterface.getInstance () . USB_SetImageEnhancement (userId, param) ) { checkCommandState (userId) { XLog.v ("$TAG setEnhanceLevel () set to $it") } } else { XLog.e ("$TAG setEnhanceLevel () set to ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } else { XLog.e ("$TAG setEnhanceLevel () ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } / *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  * ImageVideoAdjust *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  * / / *  *  * set to. * @param isMirror true-left-right false - * / suspend fun setMirror (userId: Int, rotateAngle: Int, isMirror: Boolean) { val videoAdjust = USB_IMAGE_VIDEO_ADJUST () if (JavaInterface.getInstance () . USB_GetImageVideoAdjust (userId, videoAdjust) ) { val mirrorCode: Byte = if (isMirror) (if (rotateAngle == 0 || rotateAngle == 180) 2 else 3) else 0 if (videoAdjust.byImageFlipStyle == mirrorCode) { return } XLog.i ("$TAG setMirror () ${videoAdjust.byImageFlipStyle}->$mirrorCode") videoAdjust.byImageFlipStyle = mirrorCode if (JavaInterface.getInstance () . USB_SetImageVideoAdjust (userId, videoAdjust) ) { checkCommandState (userId) { XLog.v ("$TAG setMirror () set to $it") } } else { XLog.e ("$TAG setMirror () set to ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } else { XLog.e ("$TAG setMirror () ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } / *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  * / / *  *  * . * @return Id, [JavaInterface.USB_INVALID_CHANNEL] * / suspend fun startStream (userId: Int, callback: FStreamCallBack) : Int { // set to, val videoAdjust = USB_IMAGE_VIDEO_ADJUST () if (JavaInterface.getInstance () . USB_GetImageVideoAdjust (userId, videoAdjust) ) { val isRotateChange = videoAdjust.byCorridor != 0. toByte () val isMirrorChange = videoAdjust.byImageFlipStyle != 0. toByte () if (isRotateChange || isMirrorChange) { XLog.i ("$TAG startStream () set to: , ") videoAdjust.byCorridor = 0 // 0-256x192 1-192x256 videoAdjust.byImageFlipStyle = 0 // 0 - 1-in progress 2-left-right 3 - if (JavaInterface.getInstance () . USB_SetImageVideoAdjust (userId, videoAdjust) ) { checkCommandState (userId) { XLog.v ("$TAG startStream () set to $it") } } else { XLog.e ("$TAG startStream () set to ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } } else { XLog.e ("$TAG startStream () ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } // set to // 256x392 192x520 height (192+4) * 2 (256+4) * 2 // implement, 256x192 XLog.i ("$TAG startStream () set to: 256x392") val videoParam = USB_VIDEO_PARAM () videoParam.dwVideoFormat = JavaInterface.USB_STREAM_YUY2 videoParam.dwWidth = 256 videoParam.dwHeight = 392 videoParam.dwFramerate = 25 // 25 if (JavaInterface.getInstance () . USB_SetVideoParam (userId, videoParam) ) { checkCommandState (userId) { XLog.v ("$TAG startStream () set to $it") } } else { XLog.w ("$TAG startStream () set to ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") return JavaInterface.USB_INVALID_CHANNEL } // XLog.i ("$TAG startStream () ") val callbackParam = USB_STREAM_CALLBACK_PARAM () callbackParam.dwStreamType = JavaInterface.USB_STREAM_YUY2 callbackParam.fnStreamCallBack = callback val callbackId: Int = JavaInterface.getInstance () . USB_StartStreamCallback (userId, callbackParam) if (callbackId == JavaInterface.USB_INVALID_CHANNEL) { XLog.w ("$TAG startStream () ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") return JavaInterface.USB_INVALID_CHANNEL } else { XLog.v ("$TAG startStream () ") } // set to XLog.i ("$TAG startStream () set to: 8") val streamParam = USB_THERMAL_STREAM_PARAM () streamParam.byVideoCodingType = 8 if (JavaInterface.getInstance () . USB_SetThermalStreamParam (userId, streamParam) ) { checkCommandState (userId) { XLog.v ("$TAG startStream () set to $it") } } else { XLog.w ("$TAG startStream () set to ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") return JavaInterface.USB_INVALID_CHANNEL } return callbackId } / *  *  * . * / fun removeStreamCallback (userId: Int, callbackId: Int) { if (callbackId != JavaInterface.USB_INVALID_CHANNEL) { if (!JavaInterface.getInstance () . USB_StopChannel (userId, callbackId) ) { XLog.w ("$TAG removeStreamCallback () ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } } / *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  * ThermometryBasicParam *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  *  * / / *  *  * set to * @param emissivity range `[1, 100]` * / suspend fun setEmissivity (userId: Int, emissivity: Int) { val param = USB_THERMOMETRY_BASIC_PARAM () if (JavaInterface.getInstance () . USB_GetThermometryBasicParam (userId, param) ) { if (param.dwEmissivity == emissivity) { return } XLog.i ("$TAG setEmissivity () ${param.dwEmissivity}->$emissivity") param.dwEmissivity = emissivity if (JavaInterface.getInstance () . USB_SetThermometryBasicParam (userId, param) ) { checkCommandState (userId) { XLog.v ("$TAG setEmissivity () set to $it") } } else { XLog.e ("$TAG setEmissivity () set to ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } else { XLog.e ("$TAG setEmissivity () ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } / *  *  * set to, cm * @param distance range `[30, 200]` * / suspend fun setDistance (userId: Int, distance: Int) { val param = USB_THERMOMETRY_BASIC_PARAM () if (JavaInterface.getInstance () . USB_GetThermometryBasicParam (userId, param) ) { if (param.dwDistance == distance) { return } XLog.i ("$TAG setDistance () ${param.dwDistance}cm->${distance}cm") param.dwDistance = distance if (JavaInterface.getInstance () . USB_SetThermometryBasicParam (userId, param) ) { checkCommandState (userId) { XLog.v ("$TAG setDistance () set to $it") } } else { XLog.e ("$TAG setDistance () set to ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } else { XLog.e ("$TAG setDistance () ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } / *  *  * set to (-1) / (1) /height (0) level. * / suspend fun setTemperatureMode (userId: Int, mode: Int) { val param = USB_THERMOMETRY_BASIC_PARAM () if (JavaInterface.getInstance () . USB_GetThermometryBasicParam (userId, param) ) { // Error occurredrange val oldAuto: Byte = param.byTemperatureRangeAutoChangedEnabled val oldRange: Byte = param.byTemperatureRange val newAuto: Byte = if (mode == -1) 1 else 0 // 0 - 1 - val newRange: Byte = if (mode == 1) 2 else 3 // 2 (-20~150) 3 (100~550height) if (oldAuto == newAuto && (oldRange == newRange || newRange == 1. toByte () ) ) { return } XLog.i ("$TAG setTemperatureMode () level ${getTempModeStr (oldAuto, oldRange) }->${getTempModeStr (newAuto, newRange) }") param.byTemperatureRangeAutoChangedEnabled = newAuto param.byTemperatureRange = newRange if (JavaInterface.getInstance () . USB_SetThermometryBasicParam (userId, param) ) { checkCommandState (userId) { XLog.v ("$TAG setTemperatureMode () set to $it") } } else { XLog.e ("$TAG setTemperatureMode () set to ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } else { XLog.e ("$TAG setTemperatureMode () ! Error: ${JavaInterface.getInstance () . USB_GetLastError () }") } } private fun getTempModeStr (autoEnable: Byte, range: Byte) : String { if (autoEnable == 1. toByte () ) { return "" } return if (range == 2. toByte () ) "" else "height " } private fun getCommandState (userId: Int) : Int { val state = USB_COMMAND_STATE () JavaInterface.getInstance () . USB_GetCommandState (userId, state) return state.byState. toInt () and 0xff } / *  *  * set to, * / private suspend inline fun checkCommandState (userId: Int, callback: (state: String) -> Unit) { var commandState = 1 // 1 while (commandState == 1) { commandState = getCommandState (userId) callback.invoke ("Command State: ${getCommandState (userId) . toComStateStr () }") if (commandState == 1) { // , set to 1000, low 10 delay (100) } } } private fun Int.toComStateStr () : String = when (this) { 0x00 -> "0x00: " 0x01 -> "0x01: " 0x02 -> "0x02: not allowed" 0x03 -> "0x03: mode" 0x04 -> "0x04: SET_CUR set to range" 0x05 -> "0x05: Unint ID" 0x06 -> "0x06: CS ID" 0x07 -> "0x07: " 0x08 -> "0x08: SET_CUR set to range, set to " 0x09 -> "0x09: " 0x0a -> "0x0a: " 0x0b -> "0x0b: " 0x0c -> "0x0c: " 0xff -> "0xff: " else -> "0x${this.toString (16) }: " } }